rows=[]
def glossy(key):
 return f'''<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" width="240" height="288" viewBox="0 0 240 288" role="img" aria-label="Original {key} icon"><defs><linearGradient id="surface" x1=".25" y1="0" x2=".65" y2="1"><stop stop-color="#ffffff"/><stop offset=".40" stop-color="#eef2e7"/><stop offset=".53" stop-color="#cad69c"/><stop offset=".54" stop-color="#b0c958"/><stop offset="1" stop-color="#b6e800"/></linearGradient><filter id="depth" x="-35%" y="-35%" width="180%" height="180%"><feDropShadow dx="0" dy="6" stdDeviation="5" flood-color="#182f10" flood-opacity=".5"/></filter><filter id="reflection-soft"><feGaussianBlur stdDeviation="2.5"/></filter><filter id="extrude"><feFlood flood-color="#48621a"/><feComposite in2="SourceAlpha" operator="in"/></filter><filter id="rounded"><feGaussianBlur in="SourceAlpha" stdDeviation="1.2" result="height"/><feSpecularLighting in="height" surfaceScale="3" specularConstant=".28" specularExponent="22" lighting-color="#ffffff" result="shine"><fePointLight x="20" y="-80" z="160"/></feSpecularLighting><feComposite in="shine" in2="SourceAlpha" operator="in" result="shine-cut"/><feBlend in="SourceGraphic" in2="shine-cut" mode="screen"/></filter><linearGradient id="fade" x2="0" y2="1"><stop stop-color="white" stop-opacity=".4"/><stop offset=".85" stop-color="white" stop-opacity="0"/></linearGradient><mask id="reflection"><rect x="10" y="211" width="220" height="76" fill="url(#fade)"/></mask><g id="object" transform="translate(-24 -10) scale(1.2)" fill="url(#surface)" stroke="#d8e8bb" stroke-width=".25" stroke-linejoin="round">{GLOSS[key]}</g></defs><ellipse cx="120" cy="207" rx="85" ry="10" fill="#15300b" opacity=".18"/><g filter="url(#depth)">{chr(32) if key=="avatar" else '<use xlink:href="#object" transform="translate(1.5 3)" filter="url(#extrude)"/>'}<use xlink:href="#object" filter="{'none' if key=='avatar' else 'url(#rounded)'}"/></g><g mask="url(#reflection)"><g filter="url(#reflection-soft)"><use xlink:href="#object" transform="translate(0 420) scale(1 -1)"/></g></g></svg>'''
def mini(key):
 return f'''<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 28 28" role="img" aria-label="Refined original {key} icon"><defs><linearGradient id="metal" x1=".15" y1="0" x2=".8" y2="1"><stop stop-color="#fbfcf6"/><stop offset=".42" stop-color="#d2d9c9"/><stop offset=".49" stop-color="#a4af99"/><stop offset="1" stop-color="#b5beab"/></linearGradient><filter id="s" x="-40%" y="-40%" width="190%" height="190%"><feDropShadow dx=".6" dy="1" stdDeviation=".55" flood-opacity=".45"/></filter></defs><g transform="translate(2 2)" fill="url(#metal)" stroke="#eef4e4" stroke-width=".2" stroke-linecap="round" stroke-linejoin="round" filter="url(#s)">{MINI[key]}</g></svg>'''
def button(letter):
 a,b={'A':('#d2ef76','#719e27'),'B':('#ff9984','#bd4731'),'X':('#9ddcff','#347fb6'),'Y':('#fff29b','#c59a22')}[letter]
 return f'''<svg xmlns="http://www.w3.org/2000/svg" width="64" height="64" viewBox="0 0 64 64" role="img" aria-label="Original {letter} button"><defs><radialGradient id="p" cx="35%" cy="25%" r="80%"><stop stop-color="{a}"/><stop offset="1" stop-color="{b}"/></radialGradient></defs><circle cx="32" cy="34" r="27" fill="#1d3019" opacity=".35"/><circle cx="32" cy="31" r="25" fill="url(#p)" stroke="#e8f5cf" stroke-opacity=".35" stroke-width=".6"/><ellipse cx="29" cy="18" rx="15" ry="7" fill="white" opacity=".16"/><text x="32" y="42" text-anchor="middle" font-family="Arial,sans-serif" font-size="30" font-weight="700" fill="#23371b">{letter}</text></svg>'''
def theme_hub_logo():
 import xml.etree.ElementTree as ET
 original=ET.parse(ROOT/'docs/logo.svg').getroot()
 emblem=''.join(ET.tostring(child,encoding='unicode') for child in original)
 letters={
  'T':'M1 2H21M11 2V26',
  'H':'M2 2V26M20 2V26M2 14H20',
  'E':'M21 2H2V26H21M2 14H17',
  'M':'M2 26V2L12 17L22 2V26',
  'U':'M2 2V23Q2 28 7 28H19Q24 28 24 23V2',
  'B':'M2 2V28H18Q26 28 26 21Q26 15 18 15H2M2 2H17Q25 2 25 8Q25 15 17 15'
 }
 top=''.join(f'<path d="{letters[c]}" transform="translate({i*28} 0)"/>' for i,c in enumerate('THEME'))
 bottom=''.join(f'<path d="{letters[c]}" transform="translate({i*35} 0)"/>' for i,c in enumerate('HUB'))
 return f'''<svg xmlns="http://www.w3.org/2000/svg" width="240" height="180" viewBox="0 0 240 180" role="img" aria-label="Theme Hub, green and orange dashboard wordmark"><defs><linearGradient id="orange" x2="0" y2="1"><stop stop-color="#ffe3ad"/><stop offset=".35" stop-color="#f5b348"/><stop offset=".51" stop-color="#d06f19"/><stop offset="1" stop-color="#ffa12e"/></linearGradient><linearGradient id="green" x2="0" y2="1"><stop stop-color="#b6d265"/><stop offset="1" stop-color="#7ea42c"/></linearGradient><filter id="shadow"><feDropShadow dx="0" dy="1.5" stdDeviation="1" flood-opacity=".3"/></filter></defs><g transform="translate(8 54) scale(.044) translate(-225 -225)">{emblem}</g><g filter="url(#shadow)"><g transform="translate(61 48) scale(1.12)" fill="none" stroke="url(#green)" stroke-width="2.2" stroke-linecap="square" stroke-linejoin="round">{top}</g><g transform="translate(66 89) scale(1.45 1.2)" fill="none" stroke="url(#orange)" stroke-width="6" stroke-linecap="square" stroke-linejoin="round">{bottom}</g></g></svg>'''

for k in GLOSS:(OUT/(k+'.svg')).write_text(theme_hub_logo() if k=='online' else glossy(k),encoding='utf-8')
for k in MINI:(OUT/(k+'-small.svg')).write_text(mini(k),encoding='utf-8')
for k in 'ABXY':(OUT/('button-'+k.lower()+'.svg')).write_text(button(k),encoding='utf-8')
def add(folder,file,key,label,group,notes=''):
 rows.append(dict(source=f'{folder}/{file}.png',alternative=key+'.svg',label=label,group=group,notes=notes))
for file,key,label in [('console','console-small','Console'),('friends','friends-small','Friends'),('gamertiles','achievements-small','Achievements / gamer tiles'),('live','community-small','Community'),('mail','mail-small','Mail'),('messages','messages-small','Messages'),('store','store-small','Store'),('themes','cast-themes-small','Themes')]:add('x360-nxe',file,key,label,'Small icons')
for k in 'abxy':add('x360-nxe',k,'button-'+k,k.upper()+' button - small set','Buttons')
for file,key,label in [('icon-disc','disc','Play / disc'),('icon-gamelib','games','Game library'),('icon-musiclib','music','Music library'),('icon-picturelib','pictures','Picture library'),('icon-videolib','video','Video library'),('icon-settings','settings','Settings'),('avatar-silhouette','avatar','Avatar')]:add('x360-nxe-dash',file,key,label,'Dashboard icons')
for k in 'abxy':add('x360-nxe-dash','legend-'+k,'button-'+k,k.upper()+' button - dashboard set','Buttons','Shares the same replacement as the small-set variant.')
add('x360-nxe-dash','legend-highlight','focus-small','Focus indicator','Buttons')
add('x360-nxe-dash','legend-menu','guide','Guide button','Dashboard icons','Neutral four-pane emblem; no Xbox logo.')
add('x360-nxe-dash','mobychannelzero','channel-small','Current channel marker','Small icons')
add('x360-nxe-dash','xboxlive','online','Theme Hub wordmark','Dashboard icons','Our Theme Hub tile emblem and lettering, styled in green and orange.')
(OUT/'manifest.json').write_text(json.dumps(dict(version=2,count=len(rows),items=rows),indent=2),encoding='utf-8')
(OUT/'README.md').write_text('''# Original icon alternatives - v2

Independently authored SVG paths, gradients and shadows. No Xbox bitmaps, traced paths, fonts or branding are included. The Theme Hub wordmark incorporates the owner-authored four-tile logo from docs/logo.svg. The Guide emblem is neutral. The Theme Hub wordmark uses our own tile emblem and original lettering with a green/orange glossy treatment.

27 comparison entries correspond to 23 unique SVG alternatives; duplicate A/B/X/Y variants share replacements. Avatar models are outside this icon set. Design review only: not installed in the theme.
''',encoding='utf-8')
cards=[]
for i,r in enumerate(rows):
 label=html.escape(r['label']);note=html.escape(r['notes']);src=html.escape(r['source']);alt=html.escape(r['alternative'])
 cards.append(f'''<article class="card" data-group="{r['group']}" data-label="{label.lower()}"><header><b>{i+1:02} · {label}</b><span>{r['group']}</span></header><div class="pair"><figure><div class="pad"><img src="../bundle/assets/{src}" alt="Current {label}"></div><figcaption>Current artwork</figcaption></figure><figure><div class="pad"><img src="nxe-icons-v2/{alt}" alt="Original alternative {label}"></div><figcaption>Refined SVG alternative <a href="nxe-icons-v2/{alt}" download>SVG ↗</a></figcaption></figure></div><footer>{note or 'Redrawn silhouette, fuller volume, closer lighting and reflection.'}<small>{src}</small></footer></article>''')
page='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Original icon alternatives</title><style>
*{box-sizing:border-box}body{margin:0;background:#101711;color:#e9f0e8;font:15px/1.5 system-ui,Arial}main{max-width:1600px;margin:auto;padding:40px 28px}h1{font-size:34px;font-weight:550;letter-spacing:-1px;margin:0 0 8px}p{color:#a8b9a7;max-width:980px;margin:0 0 22px}.eyebrow{text-transform:uppercase;letter-spacing:3px;color:#b6db7d;font-size:12px;margin-bottom:8px}.toolbar{display:flex;flex-wrap:wrap;gap:10px;align-items:center;margin:24px 0 28px}button,input,select{font:inherit;border:1px solid #44603b;border-radius:8px;background:#1b291b;color:#eff7e9;padding:9px 13px}button{cursor:pointer}button[aria-pressed=true]{background:#b4d875;color:#183012;border-color:#b4d875}input{margin-left:auto;min-width:180px}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px}.card{border:1px solid #354632;border-radius:12px;background:#192019;overflow:hidden}.card header{padding:14px 16px;display:flex;flex-direction:column;gap:3px}.card header span{color:#a1b49d;font-size:12px}.pair{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:#405137}.pair figure{margin:0;min-width:0;background:#1a2518}.pad{height:190px;background:radial-gradient(ellipse at 50% 10%,#759d39,#486d27 70%,#34511f);display:grid;place-items:center;overflow:hidden;padding:12px}.pad img{display:block;max-height:166px;max-width:100%;object-fit:contain}.card[data-group="Small icons"] .pad img,.card[data-group="Buttons"] .pad img{width:64px;height:64px}figcaption{padding:9px 10px;font-size:11px;color:#c0cebc;min-height:38px}a{color:#c4e996;text-decoration:none}figcaption a{float:right}.card footer{padding:11px 16px;color:#a3b49c;font-size:12px;min-height:66px}.card small{display:block;color:#6f826c;font:10px/1.8 ui-monospace,monospace}.light .pad{background:linear-gradient(#eff4e8,#c8d8b8)}.dark .pad{background:linear-gradient(#2d392b,#182116)}.actual .card[data-group="Small icons"] .pad img,.actual .card[data-group="Buttons"] .pad img{width:32px;height:32px}.count{margin-left:8px;color:#a4b99b}.toplinks{display:flex;gap:16px;margin-bottom:16px}.hidden{display:none!important}@media(max-width:1000px){.grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:650px){.grid{grid-template-columns:1fr}main{padding:24px 14px}h1{font-size:28px}input{margin-left:0;width:100%}}
</style><main><div class="eyebrow">Design study · v2 · not installed in the theme</div><h1>Refined icon alternatives</h1><p>Each current NXE interface image is on the left; its refined SVG alternative is on the right. The first draft is preserved for comparison. The former Xbox LIVE entry now uses our Theme Hub logo, with a green/orange dashboard wordmark. Guide remains a neutral emblem. Avatar models remain in the separate asset pack.</p><div class="toplinks"><a href="nxe-icon-comparison-v1.html">Compare with first draft ↗</a><a href="nxe-icons-v2.zip" download>Download original SVG pack ↓</a><a href="nxe-icons-v2/manifest.json">Manifest ↗</a></div><div class="toolbar"><button data-filter="all" aria-pressed="true">All 27</button><button data-filter="Dashboard icons">Dashboard</button><button data-filter="Small icons">Small icons</button><button data-filter="Buttons">Buttons</button><select id="background" aria-label="Comparison background"><option value="">Green surface</option><option value="dark">Dark surface</option><option value="light">Light surface</option></select><select id="scale" aria-label="Small icon size"><option value="">Small icons · 2×</option><option value="actual">Small icons · 1×</option></select><input id="search" placeholder="Find an icon…" aria-label="Find an icon"><span class="count" id="count">27 comparisons</span></div><section class="grid">'''+''.join(cards)+'''</section></main><script>
let filter='all';const cards=[...document.querySelectorAll('.card')];function refresh(){let count=0;for(const card of cards){const show=(filter==='all'||card.dataset.group===filter)&&card.dataset.label.includes(document.querySelector('#search').value.toLowerCase());card.classList.toggle('hidden',!show);if(show)count++;}document.querySelector('#count').textContent=count+' comparisons';}document.querySelectorAll('[data-filter]').forEach(button=>button.onclick=()=>{filter=button.dataset.filter;document.querySelectorAll('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',b===button));refresh();});document.querySelector('#search').oninput=refresh;function appearance(){document.body.className=[document.querySelector('#background').value,document.querySelector('#scale').value].join(' ');}document.querySelector('#background').onchange=appearance;document.querySelector('#scale').onchange=appearance;
</script></html>'''
(ROOT/'preview/nxe-icon-comparison.html').write_text(page,encoding='utf-8')
with zipfile.ZipFile(ROOT/'design/nxe-icons-v2.zip','w',zipfile.ZIP_DEFLATED) as archive:
 for path in OUT.iterdir():archive.write(path,path.name)
static=ROOT/'preview/nxe-icons-v2';static.mkdir(exist_ok=True)
for path in OUT.iterdir():shutil.copyfile(path,static/path.name)
shutil.copyfile(ROOT/'design/nxe-icons-v2.zip',ROOT/'preview/nxe-icons-v2.zip')
print('Generated',len(rows),'comparisons and',len(list(OUT.glob('*.svg'))),'original SVGs.')
